def json_file(tmpdir):
    random.seed(0)
    json_path = os.path.join(tmpdir, "test.jsonl")
    with io.open(json_path, "w", encoding="utf8") as f:
        for _ in range(UNIF1["n"]):
            data_dict = {
                "a": random.randint(0, 1),
                "b": random.randint(UNIF1["a"], UNIF1["b"]),
            }
            json.dump(data_dict, f)
            f.write("\n")
    return json_path

