def plain_context(request):
    update, readout, ch, bn, wt = request.param
    if update in updates_3dim:
        adj_type = 3
    elif update in updates_2dim:
        adj_type = 2
    else:
        raise ValueError
    data = make_data(adj_type)
    model = make_model(update, readout, ch, bn, wt)
    return model, data

