def options_factory(self, fusion, add_tested, add_reviewers, add_part_of):
        def make_options(**kwargs):
            fixture_opts = {
                'fusion': fusion,
                'add_tested': add_tested,
                'add_part_of': add_part_of,
                'add_reviewers': add_reviewers,
            }
            assert not set(fixture_opts).intersection(kwargs)
            kwargs.update(fixture_opts)
            return marge.job.MergeJobOptions.default(**kwargs)
        yield make_options

def simple(request, api):
    if api == 'cpy':
        import cpy_simple
        return cpy_simple
    elif api == 'hpy':
        import hpy_simple
        return hpy_simple
    else:
        assert False, 'Unkown param: %s' % request.param

def converter_client():
    app = Flask(__name__)
    register_converters(app)

    @app.route("/ip/<ip:ip>")
    def ip_route(ip):
        if ip in TEST_IP_ADDRS:
            return ip
        # abort 400 to differentiate from an invalid ip 404 status code
        return abort(400)

    with app.app_context():
        with app.test_client() as client:
            yield client

