def input_atoms(request):
    ndim, as_coord = request.param

    file = npz.NpzFile.read(join(data_dir("structure"), "1l2y.npz"))
    atoms = file.get_structure()

    if ndim == 2:
        # Only one model
        atoms = atoms[0]
    elif ndim == 1:
        # Only one atom
        atoms = atoms[0,0]

    if as_coord:
        return atoms.coord
    else:
        return atoms

