def experiment_id(kfp_client, tmp_path_factory, worker_id):
    if worker_id == "master":
        return get_experiment_id(kfp_client)

    # Locking taking as an example from
    # https://github.com/pytest-dev/pytest-xdist#making-session-scoped-fixtures-execute-only-once
    # get the temp directory shared by all workers
    root_tmp_dir = tmp_path_factory.getbasetemp().parent

    fn = root_tmp_dir / "experiment_id"
    with FileLock(str(fn) + ".lock"):
        if fn.is_file():
            data = fn.read_text()
        else:
            data = get_experiment_id(kfp_client)
            fn.write_text(data)
    return data

def example_graph_schema():
    def create_schema(aa=1, ab=1, ba=1, bb=1):
        # graph schema
        schema = {"A": [], "B": []}
        for ii in range(aa):
            schema["A"].append(EdgeType("A", "a%d" % ii, "A"))
        for ii in range(ab):
            schema["A"].append(EdgeType("A", "ab%d" % ii, "B"))
        for ii in range(ba):
            schema["B"].append(EdgeType("B", "ab%d" % ii, "A"))
        for ii in range(bb):
            schema["B"].append(EdgeType("B", "b%d" % ii, "B"))

        return GraphSchema(
            is_directed=False,
            node_types=sorted(schema.keys()),
            edge_types=sorted(set(it.chain(*schema.values()))),
            schema=schema,
        )

    return create_schema

