def process_env(connection_params):
    def _(*, app="app"):
        env = os.environ.copy()
        env.update(
            {
                "PROCRASTINATE_APP": f"{APP_MODULE}.{app}",
                "PROCRASTINATE_VERBOSE": "3",
                "PROCRASTINATE_DEFER_UNKNOWN": "True",
                "PGDATABASE": connection_params["dbname"],
            }
        )
        return env

    return _

async def async_app(request, async_app_explicit_open, async_app_context_manager):
    if request.param:
        yield async_app_explicit_open
    else:
        yield async_app_context_manager

def worker(running_worker):
    def func(*queues, sleep=1, app="app"):
        process = running_worker(*queues, app=app)
        time.sleep(sleep)
        process.send_signal(signal.SIGINT)
        return process.communicate()

    return func

def kill_own_pid():
    def f(signal=stdlib_signal.SIGTERM):
        os.kill(os.getpid(), signal)

    return f

def job_factory(serial, random_str):
    def factory(**kwargs):
        defaults = {
            "id": next(serial),
            "task_name": f"task_{random_str()}",
            "task_kwargs": {},
            "lock": str(uuid.uuid4()),
            "queueing_lock": None,
            "queue": f"queue_{random_str()}",
        }
        final_kwargs = defaults.copy()
        final_kwargs.update(kwargs)
        return jobs.Job(**final_kwargs)

    return factory

def entrypoint(cli_runner):
    def ep(args=""):
        # basicConfig works better if handlers config is properly isolated
        logging.getLogger("").handlers = []
        return cli_runner.invoke(cli.cli, args.split(), catch_exceptions=False)

    logging.getLogger("").handlers = []
    return ep

