                "control_scheme": 0,
                "location": [0.95, -1.75, 0.5],
            }
        ],
        "window_width": 1024,
        "window_height": 1024,
    }

    global shared_1024_env

    if shared_1024_env is None:
        binary_path = holodeck.packagemanager.get_binary_path_for_package(
            "DefaultWorlds"
